var CameraControls=class{static setup(app){let stage=document.getElementById("main-stage");if(!stage)return;let isDragging=!1,lastPos={x:0,y:0};stage.addEventListener("mousedown",e=>{e.target.closest(".workspace-overlay")||e.target.closest(".hud-overlay")||(isDragging=!0,lastPos={x:e.clientX,y:e.clientY})}),window.addEventListener("mousemove",e=>{if(!isDragging)return;let dx=e.clientX-lastPos.x,dy=e.clientY-lastPos.y;app.ctx.camera.pan(dx,dy),lastPos={x:e.clientX,y:e.clientY}}),window.addEventListener("mouseup",()=>isDragging=!1),window.addEventListener("mouseleave",()=>isDragging=!1),stage.addEventListener("wheel",e=>{if(e.target.closest(".workspace-overlay")||e.target.closest(".hud-overlay"))return;e.preventDefault();let rect=stage.getBoundingClientRect(),mx=e.clientX-rect.left,my=e.clientY-rect.top,cam=app.ctx.camera,oldZoom=cam.zoom,zoomDelta=e.deltaY*.0015,newZoom=Math.max(.1,Math.min(10,oldZoom-zoomDelta));if(newZoom===oldZoom)return;let wx=(mx-app.ctx.width/2)/oldZoom+cam.x,wy=(my-app.ctx.height*.82)/oldZoom+cam.y;cam.setZoom(newZoom);let wxAfter=(mx-app.ctx.width/2)/newZoom+cam.x,wyAfter=(my-app.ctx.height*.82)/newZoom+cam.y,dx=(wxAfter-wx)*newZoom,dy=(wyAfter-wy)*newZoom;cam.pan(dx,dy)},{passive:!1})}};export{CameraControls};
